const researchNews=[
{id:'penn-car-t-2025',areas:['Brain'],type:'institution',publisher:'Penn Medicine',date:'2025-06-01',title:'Dual-target CAR T trial reports temporary tumor reductions in recurrent glioblastoma',summary:'An early-phase study of 18 participants tested cells targeting EGFR and IL-13Rα2. Tumor reductions were often temporary; grade 3 neurotoxicity occurred in 10 participants. The report does not establish a comparative survival benefit.',therapy:'CAR T-cell therapy',phase:'Phase 1 report',trial:'NCT05168423',url:'https://www.pennmedicine.org/news/dual-target-car-t-cell-therapy-slows-growth-of-aggressive-brain-cancer'},
{id:'nci-gd2-2025',areas:['Brain'],type:'institution',publisher:'National Cancer Institute',date:'2025-01-02',title:'GD2-targeted CAR T cells investigated in diffuse midline glioma',summary:'NCI describes a small human study in children and young adults with H3K27M-mutant tumors. Some participants experienced tumor shrinkage and neurological improvement. The early findings and neurological side effects require further study.',therapy:'GD2 CAR T-cell therapy',phase:'Early clinical study',url:'https://www.cancer.gov/news-events/cancer-currents-blog/2025/car-t-cell-therapy-gd2-diffuse-midline-gliomas'},
{id:'reuters-melanoma-2024',areas:['Skin'],type:'reporting',publisher:'Reuters Health · republished by PharmaLive',date:'2024-06-03',title:'News coverage follows personalized melanoma vaccine trial',summary:'Reuters covered follow-up findings from a 157-participant study combining a personalized mRNA therapy with pembrolizumab after melanoma surgery. This historical report describes results at publication, rather than current trial availability.',therapy:'mRNA-4157 / V940 + pembrolizumab',phase:'Phase 2b follow-up',trial:'NCT03897881',url:'https://www.pharmalive.com/moderna-merck-skin-cancer-vaccine-shows-survival-benefit-in-long-term-follow-up/'},
{id:'merck-melanoma-2024',areas:['Skin'],type:'sponsor',publisher:'Moderna & Merck · Merck newsroom',date:'2024-06-03',title:'Sponsors publish three-year follow-up for KEYNOTE-942',summary:'The sponsors reported recurrence-free survival findings for V940 plus pembrolizumab versus pembrolizumab alone in resected high-risk melanoma. This is the sponsor perspective on the same study covered by Reuters, not a separate trial.',therapy:'mRNA-4157 / V940 + pembrolizumab',phase:'Phase 2b follow-up',trial:'NCT03897881',effect:'Recurrence or death: hazard ratio 0.510; 95% CI 0.288–0.906; median follow-up 34.9 months. Sponsor-reported analysis.',url:'https://www.merck.com/news/moderna-merck-announce-3-year-data-for-mrna-4157-v940-in-combination-with-keytruda-pembrolizumab-demonstrated-sustained-improvement-in-recurrence-free-survival-distant-metastasis-free-su/'},
{id:'aha-zeus-2026',areas:['Heart','Kidneys'],type:'institution',publisher:'American Heart Association',date:'2026-11-07',title:'ZEUS report: lower inflammation did not translate into fewer cardiovascular events',summary:'The association reports neutral cardiovascular outcomes for ziltivekimab in adults with atherosclerotic cardiovascular disease and chronic kidney disease, despite reduced inflammatory markers. Serious infections were more frequent with treatment.',therapy:'Ziltivekimab · IL-6 monoclonal antibody',phase:'Phase 3 results report',url:'https://newsroom.heart.org/news/researchers-say-inflammation-as-a-treatment-target-still-important-despite-neutral-results-of-zeus-trial'}
];
const newsTypes={reporting:'News reporting',institution:'Research institution',sponsor:'Sponsor announcement'};
function matchingNews(items,{bodyArea,allAreas=false,type='',query=''}={}){const terms=query.trim().toLowerCase().split(/\s+/).filter(Boolean);return items.filter(n=>(allAreas||n.areas.includes(bodyArea))&&(!type||n.type===type)&&terms.every(t=>[n.title,n.summary,n.therapy,n.publisher,n.trial||'',...n.areas].join(' ').toLowerCase().includes(t))).sort((a,b)=>b.date.localeCompare(a.date))}
function renderNews(){const chosen=document.getElementById('newsArea').value;const list=matchingNews(researchNews,{bodyArea:area,allAreas:chosen==='all',type:document.getElementById('newsType').value,query:document.getElementById('newsSearch').value});document.getElementById('newsCount').textContent=list.length+' reports';document.getElementById('newsCards').innerHTML=list.length?list.map(n=>`<article class="newscard"><span class="tag">${esc(newsTypes[n.type])}</span><span class="tag phase">${esc(n.phase)}</span><div class="newsmeta">${esc(n.publisher)} · <time datetime="${n.date}">${n.date}</time></div><h3>${esc(n.title)}</h3><p>${esc(n.summary)}</p><p><b>${esc(n.therapy)}</b></p>${n.effect?`<div class="routebox note">${esc(n.effect)}</div>`:''}<div class="note">Recruitment status: not verified by this report.</div><div class="newslinks"><a href="${esc(n.url)}" target="_blank" rel="noopener">Read source ↗</a>${n.trial?`<button class="trial-list-link" onclick="details('${esc(n.trial)}')">View trial in DrugHorizons · ${esc(n.trial)}</button>`:'<span class="note">Registry match not verified</span>'}</div></article>`).join(''):'<div class="empty">No curated reports match these filters. Try “All body systems” or clear the report search. An empty collection does not mean no research exists.</div>'}
['newsArea','newsType'].forEach(id=>document.getElementById(id).addEventListener('change',renderNews));document.getElementById('newsSearch').addEventListener('input',renderNews);
